function relancerTournee(capacite, demandes) {
  let stock = capacite;
  let livrees = 0;
  const oubliees = [];
  for (let i = 0; i < demandes.length; i++) {
    const demande = demandes[i];
    if (demande === 0) {
      continue;
    }
    if (stock >= demande) {
      stock -= demande;
      livrees += 1;
    } else {
      oubliees.push(i + 1);
    }
  }
  return { livrees: livrees, oubliees: oubliees, restants: stock };
}

