function tourneeAvecRetours(capacite, arrets) {
  let stock = capacite;
  let retours = 0;
  const livrees = [];
  const oubliees = [];
  for (const [nom, demande] of arrets) {
    if (livrees.includes(nom)) {
      continue;
    }
    if (demande > capacite) {
      oubliees.push(nom);
      continue;
    }
    if (demande > stock) {
      retours += 1;
      stock = capacite;
    }
    stock -= demande;
    livrees.push(nom);
  }
  return { livrees: livrees, oubliees: oubliees, retours: retours, restants: stock };
}

