function tourneeMinimale(routes, aLivrer, ordre) {
  const voisins = {};
  for (const [a, b, d] of routes) {
    (voisins[a] = voisins[a] || []).push([b, d]);
    (voisins[b] = voisins[b] || []).push([a, d]);
  }
  // Plus courts chemins depuis un village (on prend à chaque fois le plus proche non traité)
  function distancesDepuis(depart) {
    const dist = { [depart]: 0 };
    const traites = new Set();
    while (true) {
      let courant = null;
      for (const v of Object.keys(dist)) {
        if (!traites.has(v) && (courant === null || dist[v] < dist[courant])) {
          courant = v;
        }
      }
      if (courant === null) {
        return dist;
      }
      traites.add(courant);
      for (const [w, d] of voisins[courant] || []) {
        if (!(w in dist) || dist[courant] + d < dist[w]) {
          dist[w] = dist[courant] + d;
        }
      }
    }
  }
  const dist = {};
  for (const lieu of ["atelier", ...aLivrer]) {
    dist[lieu] = distancesDepuis(lieu);
  }
  const loin = (de, vers) => (vers in dist[de] ? dist[de][vers] : Infinity);
  let meilleur = Infinity;
  function explorer(position, restants, total) {
    if (restants.length === 0) {
      meilleur = Math.min(meilleur, total + loin(position, "atelier"));
      return;
    }
    for (const v of restants) {
      if (ordre.some(([avant, apres]) => apres === v && restants.includes(avant))) {
        continue;
      }
      explorer(v, restants.filter((r) => r !== v), total + loin(position, v));
    }
  }
  explorer("atelier", aLivrer, 0);
  return meilleur === Infinity ? -1 : meilleur;
}

