def tournee_minimale(routes, aLivrer, ordre):
    voisins = {}
    for a, b, d in routes:
        voisins.setdefault(a, []).append((b, d))
        voisins.setdefault(b, []).append((a, d))

    # Plus courts chemins depuis un village (on prend à chaque fois le plus proche non traité)
    def distances_depuis(depart):
        dist = {depart: 0}
        traites = set()
        while True:
            courant = None
            for v in dist:
                if v not in traites and (courant is None or dist[v] < dist[courant]):
                    courant = v
            if courant is None:
                return dist
            traites.add(courant)
            for w, d in voisins.get(courant, []):
                if w not in dist or dist[courant] + d < dist[w]:
                    dist[w] = dist[courant] + d

    dist = {}
    for lieu in ["atelier"] + aLivrer:
        dist[lieu] = distances_depuis(lieu)
    infini = float("inf")

    def loin(de, vers):
        return dist[de].get(vers, infini)

    meilleur = [infini]

    def explorer(position, restants, total):
        if not restants:
            meilleur[0] = min(meilleur[0], total + loin(position, "atelier"))
            return
        for v in restants:
            if any(apres == v and avant in restants for avant, apres in ordre):
                continue
            explorer(v, [r for r in restants if r != v], total + loin(position, v))

    explorer("atelier", aLivrer, 0)
    return -1 if meilleur[0] == infini else meilleur[0]

